/**
 * Code3 — builds Gmail RFC822 'raw' and decides next step.
 * Fix: normalize Google Sheet keys that contain trailing spaces.
 */

// =============== Helpers ===============
const isYes = v =>
  String(v ?? '').trim().toLowerCase() === 'yes' ||
  String(v ?? '').trim() === '1' ||
  String(v ?? '').trim().toLowerCase() === 'true';

const isNo = v =>
  v == null ||
  String(v).trim() === '' ||
  String(v).trim().toLowerCase() === 'no' ||
  String(v).trim() === '0' ||
  String(v).trim().toLowerCase() === 'false';

const stripHidden = s =>
  String(s ?? '')
    .replace(/\u200B|\u200C|\u200D|\u2060|\uFEFF|\u00A0/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

const extractEmail = raw => {
  const s = stripHidden(raw).replace(/^"+|"+$/g, '');
  let m = s.match(/<\s*([^>]+)\s*>/);
  if (m && m[1]) return m[1].trim();
  const first = s.split(',')[0].trim();
  m = first.match(/([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})/i);
  return m ? m[1].trim() : '';
};

const emailOk = e => /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(e);

// =============== Input (normalize keys/values) ===============
const row = $input.item.json;
const r = {};
for (const k of Object.keys(row)) {
  const trimmedKey = k.trim();
  const v = row[k];
  r[trimmedKey] = typeof v === 'string' ? v.trim() : v;
}

// =============== Early exits ===============
if (isYes(r.replied) || isYes(r.opted_out)) {
  return [{ json: { ...r, skip: true, skip_reason: 'replied_or_opted_out' } }];
}

// =============== Decide which step to send ===============
let step = null;
if (isNo(r.email1_sent)) step = 1;
else if (isNo(r.email2_sent)) step = 2;
else if (isNo(r.email3_sent)) step = 3;

if (!step) {
  return [{ json: { ...r, skip: true, skip_reason: 'all_steps_already_sent' } }];
}

// =============== Select subject/body ===============
let selected_subject = '';
let selected_body = '';

if (step === 1) {
  selected_subject = String(r.email1_subject ?? '');
  selected_body    = String(r.email1_body ?? '');
} else if (step === 2) {
  selected_subject = String(r.email1_subject ?? ''); // reuse subject
  selected_body    = String(r.email2_body ?? '');
} else {
  selected_subject = String(r.email3_subject ?? r.email1_subject ?? '');
  selected_body    = String(r.email3_body ?? '');
}

// =============== Resolve addresses robustly ===============
const candidateTo = [r.email, r['Email Address'], r.recipient_email, r.to];
const candidateFrom = [r.sender_email, r.from];

const to   = extractEmail(candidateTo.find(v => v != null && String(v).trim() !== ''));
const from = extractEmail(candidateFrom.find(v => v != null && String(v).trim() !== ''));

if (!to || !emailOk(to)) {
  return [{ json: { ...r, skip: true, skip_reason: 'invalid_or_missing_recipient_email', details: { toRaw: candidateTo, toParsed: to } } }];
}
if (!from || !emailOk(from)) {
  return [{ json: { ...r, skip: true, skip_reason: 'invalid_or_missing_sender_email', details: { fromRaw: candidateFrom, fromParsed: from } } }];
}

// =============== Build RFC822 (plain text) ===============
const displayNameTo = stripHidden(`${r.first_name ?? ''} ${r.last_name ?? ''}`);
const rfc822 =
  `From: <${from}>\r\n` +
  `To: ${displayNameTo ? `"${displayNameTo}" ` : ''}<${to}>\r\n` +
  `Subject: ${selected_subject}\r\n` +
  `MIME-Version: 1.0\r\n` +
  `Content-Type: text/plain; charset="UTF-8"\r\n` +
  `Content-Transfer-Encoding: 7bit\r\n\r\n` +
  `${selected_body}`;

const raw = Buffer.from(rfc822, 'utf8')
  .toString('base64')
  .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

// =============== Output ===============
return [{
  json: {
    ...r,
    sequence_step: step,
    recipient_email: to,
    sender_email: from,
    selected_subject,
    selected_body,
    raw
    // If replying to an existing thread: threadId: r.message_id
  }
}];

